@startuml

class Employee {}

class HeadCoach extends Employee {}

class Director extends Employee {}

class Scout extends Employee {}

class HeadScout extends Scout {}

class PlayerProfile {
  + targetPositions : string[]
}

class PlayerAttribute {
  + name : string
  + value : float
}

class Player {
  + name : string
}

class LongList {
  + evaluationDate : date
}

class ScoutingAssignment {
  + status : string
}

class ScoutingReport {
  + pros : string
  + cons : string
  + recommendation : string
}

class ShortList {}

class OfficialOffer {}

PlayerProfile "1" *-- "*" PlayerAttribute
PlayerProfile "1" -- "*" Player : matches
LongList "1" -- "*" Player : contains
ScoutingAssignment "1" -- "1" Player : investigates
ScoutingAssignment "1" -- "1" Scout : assigned to
ScoutingAssignment "1" -- "0..1" ScoutingReport : results in
ShortList "1" -- "*" Player : contains
Director "1" -- "*" OfficialOffer : makes
OfficialOffer "1" -- "1" Player : for

@enduml

